.ds-task-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid var(--line, #808080);
}
.ds-task-entry {
  display: flex;
  flex-direction: column;
  padding: 40px 48px 0 0;
  min-width: 0;
}
.ds-task-entry + .ds-task-entry {
  padding: 40px 0 0 48px;
  border-left: 1px solid var(--line, #808080);
}
.ds-task-entry h3 {
  min-height: 2.3em;
  font: 500 var(--type-section, clamp(2rem, 3.4vw, 3rem))/1.15 var(--font-heading, 'Instrument Sans', 'Segoe UI', sans-serif);
  letter-spacing: -0.025em;
  margin: 0 0 24px;
  max-width: 15ch;
}
.ds-tool-feature {
  position: relative;
  isolation: isolate;
  background: var(--canvas, #151515);
}
.ds-tool-feature {
  flex: 1;
  display: flex;
  align-items: start;
  min-height: 560px;
  padding: 144px 32px 32px;
}
.ds-tool-banner {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}
.ds-tool-feature::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}
.ds-tool-feature::before {
  background: linear-gradient(
    to bottom,
    rgb(21 21 21 / 0.04),
    rgb(21 21 21 / 0.3) 80px,
    rgb(21 21 21 / 0.78) 120px,
    rgb(21 21 21 / 0.92)
  );
}
.ds-tool-presentation {
  position: relative;
  z-index: 2;
  width: 100%;
  min-width: 0;
}
.ds-tool-feature .ds-tool-status {
  color: var(--secondary, #c2c2c2);
}
.ds-tool-identity {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  font-size: var(--type-label, 0.9375rem);
}
.ds-tool-status {
  font-size: var(--type-meta, 0.875rem);
  line-height: 1.6;
  color: var(--quiet, #a2a2a2);
  margin: 0;
}
.ds-tool-identity .ds-tool-status {
  width: 100%;
}
.ds-tool-tagline {
  font-size: clamp(1.125rem, 1.6vw, 1.375rem);
  line-height: 1.55;
  color: var(--secondary, #c2c2c2);
  max-width: 45ch;
  margin: 24px 0 32px;
}
.ds-tool-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 24px;
}
.ds-text-link,
.ds-primary-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  max-width: 100%;
  line-height: 1.4;
  font-size: var(--type-label, 0.9375rem);
  font-weight: 500;
}
.ds-text-link {
  color: var(--action, #dedede);
  text-underline-offset: 0.25em;
}
.ds-text-link:hover {
  color: var(--action-hover, #ffffff);
}
.ds-primary-link {
  padding: 12px 20px;
  background: var(--accent, #aabad9);
  color: var(--canvas, #151515);
  border: 1px solid transparent;
  border-radius: 16px;
  text-decoration: none;
}
.ds-primary-link:hover {
  color: var(--canvas, #151515);
  text-decoration: underline;
}
.ds-background-frame {
  position: relative;
}
.ds-background-frame::before,
.ds-background-frame::after {
  content: '';
  position: absolute;
  inset-block: 0;
  width: calc(var(--page-gutter, clamp(20px, 4vw, 64px)) - 12px);
  background-image: url("data:image/png;base64,");
  pointer-events: none;
  user-select: none;
}
.ds-background-frame::before {
  left: 0;
  border-left: 1px solid color-mix(in srgb, var(--line, #808080) 22%, transparent);
}
.ds-background-frame::after {
  right: 0;
  border-right: 1px solid color-mix(in srgb, var(--line, #808080) 22%, transparent);
}
.ds-background-hatch {
  background-image: repeating-linear-gradient(
    135deg,
    transparent 0 4px,
    color-mix(in srgb, var(--line, #808080) 28%, transparent) 4px 5px,
    transparent 5px 8px
  );
}
.ds-background-hatch {
  position: absolute;
  left: var(--page-gutter, clamp(20px, 4vw, 64px));
  bottom: 32px;
  width: 96px;
  height: 12px;
  pointer-events: none;
  user-select: none;
}
